import test from'node:test';import assert from'node:assert/strict';import{readFileSync,writeFileSync,mkdtempSync,mkdirSync,rmSync}from'node:fs';import{tmpdir}from'node:os';import{join}from'node:path';import{spawnSync,execFileSync}from'node:child_process';
import{ORIGINAL,REPAIRED,repairDeployScript,recoveryWrapper,requireOriginalFailedAttempt}from'./forward_internal_preflight.mjs';
const frozen=readFileSync(new URL('../../../../deploy/deploy.sh',import.meta.url),'utf8');
test('full frozen deployment spine differs only in the one exact interop expression',()=>{const fixed=repairDeployScript(frozen);assert.equal(fixed.replace(REPAIRED,ORIGINAL),frozen);assert.equal(frozen.split(ORIGINAL).length,2);assert.equal(fixed.split(REPAIRED).length,2);execFileSync('/bin/bash',['-n'],{input:recoveryWrapper(frozen)});for(const gate of['scripts/check-audit-chain-gate.ts','stage "$AIHR_SELECTED_DEPLOY_REF"','pnpm db:migrate','activate "$AIHR_SELECTED_DEPLOY_REF"','confirm-runtime "$AIHR_SELECTED_DEPLOY_REF"'])assert(fixed.includes(gate),gate);});
test('missing or duplicate internal preflight refuses rather than broad rewriting',()=>{assert.throws(()=>repairDeployScript('changed format'));assert.throws(()=>repairDeployScript(frozen+'\n'+ORIGINAL));});
const code=(path)=>`const imported=await import(${JSON.stringify(path)});const {internalConfig}=imported.default??imported;internalConfig();`;
for(const format of['cjs','mjs'])test(`real Node22 ${format} namespace invokes actual configuration validator`,()=>{const dir=mkdtempSync(join(tmpdir(),'aihr-auth-forward-'));try{const path=join(dir,'config.'+format);const fn=`function internalConfig(){if(process.env.AUTH_TEST!=='valid')throw Error('Configuration refused');}`;writeFileSync(path,format==='cjs'?fn+`module.exports=Object.fromEntries([['internalConfig',internalConfig]]);`:'export '+fn);const valid=spawnSync(process.execPath,['--input-type=module','-e',code(path)],{env:{PATH:process.env.PATH,AUTH_TEST:'valid'},encoding:'utf8'});assert.equal(valid.status,0,valid.stderr);const invalid=spawnSync(process.execPath,['--input-type=module','-e',code(path)],{env:{PATH:process.env.PATH,AUTH_TEST:'invalid'},encoding:'utf8'});assert.notEqual(invalid.status,0);assert.match(invalid.stderr,/Configuration refused/);if(format==='cjs'){const old=spawnSync(process.execPath,['--input-type=module','-e',`import {internalConfig} from ${JSON.stringify(path)};internalConfig();`],{env:{PATH:process.env.PATH,AUTH_TEST:'valid'},encoding:'utf8'});assert.notEqual(old.status,0);assert.match(old.stderr,/Named export|does not provide an export/);}}finally{rmSync(dir,{recursive:true,force:true});}});
test('missing internalConfig export still refuses',()=>{const dir=mkdtempSync(join(tmpdir(),'aihr-auth-missing-'));try{const path=join(dir,'config.cjs');writeFileSync(path,'module.exports={unrelated:true};');const r=spawnSync(process.execPath,['--input-type=module','-e',code(path)],{encoding:'utf8'});assert.notEqual(r.status,0);assert.match(r.stderr,/not a function/);}finally{rmSync(dir,{recursive:true,force:true});}});
test('external recovery wrapper preserves original script zero and argument boundaries',()=>{const dir=mkdtempSync(join(tmpdir(),'aihr-auth-argv-'));try{const fixture='#!/bin/bash\n#'+ORIGINAL+'\nprintf "%s\\n" "$0" "$#" "$@"\n';const path=join(dir,'run.sh');writeFileSync(path,recoveryWrapper(fixture));const output=execFileSync('/bin/bash',[path,'--ci-build=fixture','--testing-build-record=original','argument with spaces'],{encoding:'utf8'});assert.deepEqual(output.trim().split('\n'),['/opt/ai-hr/deploy/deploy.sh','3','--ci-build=fixture','--testing-build-record=original','argument with spaces']);}finally{rmSync(dir,{recursive:true,force:true});}});
test('recovery admission requires this failed preflight and unchanged old build',()=>{const grant={baselineBuildId:'old'};const v={state:'failed',phase:'preflight',ref:'9541b1686d7941f89e564723271e48bf85a21a89',built_ref:'2127b1a7ebd40e5b9ee7d010e72e75d4b1cb3e9f',build_id:'old',built_build_id:'old',stale_build:'1',exit_code:'1'};requireOriginalFailedAttempt(v,grant);for(const[key,value]of[['state','running'],['phase','migrate'],['ref','other'],['built_ref','new'],['build_id','new'],['built_build_id','new'],['stale_build','0'],['exit_code','0']])assert.throws(()=>requireOriginalFailedAttempt({...v,[key]:value},grant));});
